"""Generate public catalogue data and written assessments from catalog.json (stdlib only)."""
import csv,json,pathlib
root=pathlib.Path(__file__).resolve().parents[1]
apps=json.loads((root/'catalog.json').read_text())
(root/'catalog-data.js').write_text('window.OECS_CATALOG = '+json.dumps(apps,indent=2,ensure_ascii=False)+';\n')
fields=['id','title','industry','status','review_level','url','related_url','value','evidence','gap','acceptance','commercial','priority','reviewed_on']
with (root/'review/assessment.csv').open('w',newline='',encoding='utf-8-sig') as f:
 w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');w.writeheader();w.writerows(apps)
p=['# OECS Software Portfolio Review','Reviewed 10 November 2026. Scope: all 42 original GitHub marketplace listings.','## Executive finding','The portfolio contains potentially useful business applications, demonstrators, marketing websites and feasibility documents. It cannot responsibly be described as 42 independently verified production SaaS products. Fifteen original /apps/ launch paths returned 404. The other 27 original routes served the company web-app shell; the company portfolio supplied the actual destinations.','There are 32 matching public launch destinations, nine exact editions not recovered and one access-restricted destination. Existing listing names are retained for traceability, including original compliance claims in names; names are not endorsements. No production-readiness certification is given.','## Scope and evidence','GET checks established HTTP reachability only. Public source, application bundles and rendered interface text were inspected as available. FaMaaS IFRS demo setup opened its sample dashboard. QuickBooks Cleanup loaded 25 sample accounts and showed a validation preview with 14 steps. The financial framework studio interface was labelled local/single-tenant and flagged an unbalanced initial TB. An authenticated payroll workspace was viewed without running payroll or changing records. No private employee, payroll or patient records are reproduced.','Live payment processing, actual QuickBooks writes, external messages, statutory correctness, production tenancy, backups and full end-to-end functionality were not tested. Missing evidence or a bare HTTP 403 is a limitation, not proof of a defect. Published engineering return figures were not independently recalculated. This is technical/commercial screening, not financial, legal, clinical or regulatory certification.','## Commercial priorities','Focus on FaMaaS, QuickBooks Cleanup, Audit Studio and payroll for controlled acceptance tests. This is an analyst judgment based on workflow visibility and business use, not a comparative valuation. Validate a bounded workflow, delivery costs and customer demand before subscription pricing. Keep feasibility/proposal work separate from operational software. Consolidate the MLS/Realtors aliases and duplicate/module offers.','Suggested sequence: first 30 days—recover exact editions and prepare synthetic acceptance tests; days 31–60—prove persistence, isolation, integration failure handling and recovery; days 61–90—run a customer pilot, measure outcomes and support effort, then agree pricing. Timeline is illustrative.','## Platform changes','Rebuilt the catalogue with search, sector/status filters, sorting, individual assessments, comparisons of up to three apps, browser-local shortlist, shareable assessment links, email draft inquiries and printable review. Removed simulated Google sign-in/admin controls and iframe launch behavior. Original local-storage URL overrides no longer supersede published links. index1.html now redirects to the canonical catalogue. No underlying app backend was changed.','## Individual assessments']
for a in apps:
 p += [f"### {a['id']:02d}. {a['title']}",f"Status: **{a['status']}**. Review scope: {a['review_level']}.",f"**Business value:** {a['value']}",f"**Observed:** {a['evidence']}",f"**Gap:** {a['gap']}",f"**Acceptance test:** {a['acceptance']}",f"**Commercial route:** {a['commercial']}"]
 if a['url']:p += [f"Current destination: [{a['url']}]({a['url']})"]
 if a['source_url']:p += [f"Matching source: [{a['source_url']}]({a['source_url']})"]
 if a['related_url']:p += [f"Related material — different edition: [{a['related_url']}]({a['related_url']})"]
p += ['## Evidence files','- original-link-audit.json: original 42 GET checks, including body hashes.','- destination-audit.json: actual destinations obtained from the company portfolio and their GET responses.','- github-pages-audit.json: recovered matching demonstration URLs.','- additional-destinations.json: IFRS studio and payroll URLs.','- bundle-audit.json: public bundle URLs and superficial code counts, used only as navigation/inspection aids. Counts of fetch, storage or demo strings are not functionality or security scores.','- current-link-audit.json: final destination and related-link GET checks.','- VALIDATION.md: rebuilt catalogue validation and limitations.','All checks are point-in-time. Domain availability and application behavior may change.']
(root/'review/PORTFOLIO_REVIEW.md').write_text('\n\n'.join(p)+'\n')
